-- Generated by scripts/build-cad-source-renewal-catalog.ts.
-- Activate after ask-bob/bob-worker support explicit checked source renewal.
-- Preserve model, reasoning, work policy and every historical manifest.
begin;
do $cad_source_renewal_catalog$
declare
 patch jsonb:=$cad_source_renewal${
  "manual": "Keep the same drawing request_id and all saved requirements when its construction is corrected. If the pinned construction revision is older than its current saved version, read and check that SAME construction, then explicitly pass the new exact receipt construction_revision with handoff:null and requirement_changes:[]. This renews the existing request after source/readiness checks and discards obsolete candidates, approvals and retries. Do not create a duplicate request or construction to escape a revision conflict. Omitted revisions never select a new head, and rendering never invents missing construction data. Recheck the independent review, saved receipt and readback before claiming delivery.",
  "revision_description": "Copy the exact saved/read construction revision. On retry retain the pinned version. To renew an existing request after revising and checking that SAME construction, explicitly pass its newer current receipt revision with the same request_id and handoff:null. The server preserves requirements, discards obsolete candidates/retries and checks readiness and sources again. It never follows a newer head implicitly or changes construction identity."
}$cad_source_renewal$::jsonb;
 prior shared.ai_prompt_versions; version_uuid uuid; next_version integer;
 definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.design_project_cad';
 if not found then raise exception 'cad_source_renewal_tool_missing'; end if;
 if prior.metadata->>'publication'='cad-source-renewal-v1' then raise exception 'cad_source_renewal_already_published'; end if;
 if prior.definition#>>'{parameters,properties,construction_revision,type}' is distinct from 'integer' then raise exception 'cad_source_renewal_schema_changed'; end if;
 definition:=jsonb_set(prior.definition,'{parameters,properties,construction_revision,description}',patch->'revision_description');
 definition:=jsonb_set(definition,'{additional_description}',to_jsonb(coalesce(prior.definition->>'additional_description','')||E'

'||(patch->>'manual')));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
 values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','cad-source-renewal-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=jsonb_build_object('tools.design_project_cad',version_uuid);
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools';
 if not found or not exists(select 1 from jsonb_array_elements(prior.definition->'catalog') r where r->>'name'='design_project_cad') then raise exception 'cad_source_renewal_toolbox_missing'; end if;
 definition:=jsonb_set(prior.definition,'{catalog}',(select jsonb_agg(case when r->>'name'='design_project_cad' then jsonb_set(r,'{how_to}',to_jsonb(coalesce(r->>'how_to','')||E'

'||(patch->>'manual'))) else r end order by n) from jsonb_array_elements(prior.definition->'catalog') with ordinality as rows(r,n)));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
 values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','cad-source-renewal-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 update bob.tool_catalog set how_to=coalesce(how_to,'')||E'

'||(patch->>'manual') where name='design_project_cad';
 if not found then raise exception 'cad_source_renewal_live_policy_missing'; end if;
 perform shared.activate_ai_catalog('bob',activation);
end $cad_source_renewal_catalog$;
commit;
